//! Public Coverage supplies both the stored bytes and independent native XML.
//! No expected row is generated by the converter under test.
use super::*;
use crate::metadata_model::brace::{Brace, parse_row, serialize};
use crate::metadata_model::{DescriptorContext, compile_descriptor};
use ibcmd_v8::reader::StreamingReader;
use std::io::Cursor;

fn decode_base64(source: &[u8]) -> Vec<u8> {
    let (mut out, mut word, mut bits) = (Vec::new(), 0u32, 0u8);
    for &byte in source {
        let value = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' | b'\r' | b'\n' => continue,
            _ => panic!("invalid fixture base64"),
        };
        word = (word << 6) | u32::from(value);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((word >> bits) as u8);
            word &= (1 << bits) - 1;
        }
    }
    out
}

fn rows(root: &Path) -> Vec<MetadataTextRow> {
    let cf = decode_base64(&fs::read(root.join("configuration.cf.b64")).unwrap());
    let mut reader = StreamingReader::open_default(Cursor::new(cf)).unwrap();
    let names = reader
        .index()
        .entries
        .iter()
        .map(|e| e.name.clone())
        .collect::<Vec<_>>();
    names
        .iter()
        .enumerate()
        .filter_map(|(index, name)| {
            if uuid::Uuid::parse_str(name).is_err() {
                return None;
            }
            let bytes = reader.read_entry_data(index).unwrap()?;
            metadata_text_row_from_blob(name, &bytes)
        })
        .collect()
}

fn legacy_xml(
    row: &MetadataTextRow,
    rows: &[MetadataTextRow],
    version: InfobaseConfigSourceVersion,
) -> Option<Vec<u8>> {
    let types = build_metadata_type_index_from_texts(rows);
    let refs = refs::build_metadata_object_reference_index_from_texts(rows);
    extract_metadata_source_xml_from_text_row(
        row,
        &types,
        &Default::default(),
        &refs,
        &refs,
        &refs,
        &Default::default(),
        &Default::default(),
        &Default::default(),
        &Default::default(),
        &Default::default(),
        &Default::default(),
        version,
    )
    .map(|x| source_xml_file_bytes(x.xml, version))
}

const SETS: [(&str, &str, &str); 7] = [
    ("commonattributes", "CommonAttributes", "CommonAttribute"),
    ("constants", "Constants", "Constant"),
    ("businessprocesses", "BusinessProcesses", "BusinessProcess"),
    ("tasks", "Tasks", "Task"),
    ("exchangeplans", "ExchangePlans", "ExchangePlan"),
    (
        "chartsofcalculationtypes",
        "ChartsOfCalculationTypes",
        "ChartOfCalculationTypes",
    ),
    (
        "calculationregisters",
        "CalculationRegisters",
        "CalculationRegister",
    ),
];

fn first_owner_difference(compiled: &Brace, native: &Brace, path: &str) -> Option<String> {
    if compiled == native {
        return None;
    }
    match (compiled, native) {
        (Brace::List(a), Brace::List(b)) => {
            for (i, (a, b)) in a.iter().zip(b).enumerate() {
                if let Some(diff) = first_owner_difference(a, b, &format!("{path}[{i}]")) {
                    return Some(diff);
                }
            }
            Some(format!(
                "{path}: compiled arity {}, native arity {}",
                a.len(),
                b.len()
            ))
        }
        (Brace::Atom(a), Brace::Atom(b)) | (Brace::Str(a), Brace::Str(b)) => {
            Some(format!("{path}: compiled={a:?}, native={b:?}"))
        }
        _ => Some(format!("{path}: node kinds differ")),
    }
}

#[test]
fn tool1cd_metadata_public_coverage_scalars_match_native_and_compile_same_owner() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/coverage");
    for (platform, version) in [
        ("8.3.27.2342", InfobaseConfigSourceVersion::V2_20),
        ("8.5.1.1150", InfobaseConfigSourceVersion::V2_21),
    ] {
        for (set, folder, kind) in SETS {
            let set_root = root.join(platform).join(set);
            let rows = rows(&set_root);
            let native = set_root.join("native");
            let context = DescriptorContext::new(&native, version.as_str()).unwrap();
            for entry in fs::read_dir(native.join(folder)).unwrap() {
                let path = entry.unwrap().path();
                if path.extension().and_then(|x| x.to_str()) != Some("xml") {
                    continue;
                }
                let expected = fs::read(&path).unwrap();
                let xml = crate::metadata_model::xml::parse_element_tree(&expected).unwrap();
                let id = xml.child(kind).unwrap().attr("uuid").unwrap();
                let row = rows.iter().find(|r| r.file_name == id).unwrap();
                let emitted = legacy_xml(row, &rows, version)
                    .unwrap_or_else(|| panic!("{platform}/{set}: {} refused", path.display()));
                assert!(
                    emitted == expected,
                    "native XML {platform}/{set}: {} differs at byte {:?}",
                    path.display(),
                    emitted.iter().zip(&expected).position(|(a, b)| a != b)
                );
                let compiled_bytes = compile_descriptor(kind, &path, &expected, &context).unwrap();
                let packed = ibcmd_cf::payload::encode_payload(
                    ibcmd_cf::payload::PayloadEncoding::RawDeflate,
                    &compiled_bytes,
                    ibcmd_core::limits::ResourceLimits::default(),
                )
                .unwrap();
                let inverse = metadata_text_row_from_blob(&row.file_name, &packed).unwrap();
                let inverse_xml = legacy_xml(&inverse, &rows, version)
                    .expect("compiled owner must decode through the independent legacy reader");
                assert_eq!(
                    inverse_xml,
                    expected,
                    "semantic inverse {platform}/{set}: {}",
                    path.display()
                );
                let mut original = parse_row(row.text.as_bytes()).unwrap();
                let compiled = parse_row(&compiled_bytes).unwrap();
                if kind == "Task" {
                    // These two valid internal UUIDs are not represented by native XML.
                    // All source semantics and every other owner member remain exact.
                    for slot in
                        ibcmd_schema::tool1cd_metadata::TaskScalarLayout::INTERNAL_UUID_FIELDS
                    {
                        let value = original.at(&[1, slot]).unwrap().as_atom().unwrap();
                        uuid::Uuid::parse_str(value)
                            .expect("native Task internal carrier is a UUID");
                        assert_eq!(compiled.at(&[1, slot]).unwrap(), &Brace::nil_uuid());
                        original.as_list_mut().unwrap()[1].as_list_mut().unwrap()[slot] =
                            Brace::nil_uuid();
                    }
                }
                assert!(
                    compiled.at(&[1]) == original.at(&[1]),
                    "native owner {platform}/{set}: {} differs: {}",
                    path.display(),
                    first_owner_difference(
                        compiled.at(&[1]).unwrap(),
                        original.at(&[1]).unwrap(),
                        "owner"
                    )
                    .unwrap_or_default()
                );
            }
        }
    }
}

#[test]
fn tool1cd_metadata_unknown_flags_refuse_instead_of_defaulting() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/coverage/8.5.1.1150");
    for (set, folder, kind) in SETS {
        let set_root = root.join(set);
        let rows = rows(&set_root);
        let path = set_root.join("native").join(folder).join("CovTemplate.xml");
        let expected = fs::read(path).unwrap();
        let xml = crate::metadata_model::xml::parse_element_tree(&expected).unwrap();
        let id = xml.child(kind).unwrap().attr("uuid").unwrap();
        let original = rows.iter().find(|r| r.file_name == id).unwrap();
        let paths: &[&[usize]] = match kind {
            "CommonAttribute" => &[
                &[1, 6],
                &[1, 11],
                &[1, 1, 2],
                &[1, 1, 5],
                &[1, 1, 7],
                &[1, 1, 13],
                &[1, 1, 17],
                &[1, 1, 20],
            ],
            "Constant" => &[&[1, 15], &[1, 16]],
            "BusinessProcess" => &[&[1, 19], &[1, 20], &[1, 31]],
            "Task" => &[&[1, 20], &[1, 21], &[1, 23], &[1, 50], &[1, 51]],
            "ExchangePlan" => &[&[1, 47], &[1, 48]],
            "ChartOfCalculationTypes" => &[&[1, 24], &[1, 35], &[1, 39]],
            "CalculationRegister" => &[&[1, 24], &[1, 25]],
            _ => unreachable!(),
        };
        for path in paths {
            let mut brace = parse_row(original.text.as_bytes()).unwrap();
            let mut cursor = &mut brace;
            for index in *path {
                cursor = &mut cursor.as_list_mut().unwrap()[*index];
            }
            *cursor = Brace::num(9);
            let mut changed = original.clone();
            changed.text = serialize(&brace);
            assert!(
                legacy_xml(&changed, &rows, InfobaseConfigSourceVersion::V2_21).is_none(),
                "{kind} accepted unknown flag at {path:?}"
            );
        }
    }
}
